mustKnow.code:
-- expand: เพิ่มคอลัมน์ใหม่ โค้ดเก่ายังใช้ phone ได้
ALTER TABLE users ADD COLUMN mobile text;
-- migrate: แอปเขียนทั้งสองคอลัมน์ แล้ว backfill ข้อมูลเก่า
UPDATE users SET mobile = phone WHERE mobile IS NULL;
-- contract: เมื่อทุกบริการอ่านจาก mobile และเลิกเขียน phone แล้ว
ALTER TABLE users DROP COLUMN phone;

